class IperfDataTransfer(LteDataTransfer):
    """Managing iperf based data transfer."""
    def __init__(self, name, dt_definition, configuration, logger_name='ute_ue'):
        """
        Basic initialization.

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        """
        super().__init__(name=name, dt_definition=dt_definition, configuration=configuration,
                                                logger_name=logger_name)
        dt_def_dict = {'protocol': dt_definition.protocol,
                       'duration': dt_definition.duration,
                       'direction': dt_definition.direction,
                       'ul_throughput': dt_definition.ul_throughput,
                       'dl_throughput': dt_definition.dl_throughput,
                       'protocol_details': dt_definition.protocol_details}
        configuration = copy.deepcopy(configuration)
        iperf_conf = self._create_iperf_configuration(dt_definition, configuration)
        self.cmd_options = CmdOptions(traffic_definition=dt_def_dict, configuration=iperf_conf)
        self.ue_endpoint = UeEndpoint(name, dt_definition, configuration, self.cmd_options, self.logger)
        self.appsvr_endpoint = AppSvrEndpoint(name, dt_definition, configuration, self.cmd_options, self.logger)
        self._publisher = None
        self._statistics = None

    @staticmethod
    def _create_iperf_configuration(dt_definition, configuration):
        # due to historical reasons some parameters may come from dt_definition
        # but CmdOptions accepts them only from configuration (where they conceptually belong)
        # that's why we do this overwriting here
        iperf_conf = {'iperf': configuration['iperf']} if 'iperf' in configuration else {}

        for overwrite_param in ['buffer_length', 'print_mss', 'parallel', 'interval']:
            if overwrite_param in dt_definition.protocol_details:
                param_value = dt_definition.protocol_details[overwrite_param]
                if 'iperf' in iperf_conf:
                    iperf_conf['iperf'][overwrite_param] = param_value
                else:
                    iperf_conf['iperf'] = {overwrite_param: param_value}

        return iperf_conf

