    @property
    def duration(self):
        """Duration option to use for iperf command"""
        return self.cmd_options.duration

    @property
    def port(self):
        """Port to use for iperf command"""
        iperf_port = self.server_endpoint.iperf_port
        if iperf_port is None:
            iperf_port = self.cmd_options.port
        return iperf_port

    @property
    def ue_ip(self):
        """IP of UE"""
        return self.ue_endpoint.endpoint_ip

    @property
    def app_server_ip(self):
        """IP of Application Server"""
        return self.appsvr_endpoint.endpoint_ip

    @property
    def client_endpoint(self):
        """Access endpoint where iperf client is running (UE or AppSvr)"""
        if self.direction == 'dl':  # for downlink traffic iperf client runs on application server
            return self.appsvr_endpoint
        else:
            return self.ue_endpoint

    @property
    def server_endpoint(self):
        """Access endpoint where iperf server is running (UE or AppSvr)"""
        if self.direction == 'dl':  # for downlink traffic iperf server runs on UE PC
            return self.ue_endpoint
        else:
            return self.appsvr_endpoint

    @property
    def client_options(self):
        """Generate options for iperf client command"""
        return self.client_endpoint.client_options(self.server_endpoint.endpoint_ip, self.port)

    @property
    def server_options(self):
        """Generate options for iperf server command"""
        return self.server_endpoint.server_options(self.client_endpoint.endpoint_ip)

    @property
    def iperf_client(self):
        """Access moler Command object for iperf client"""
        return self.client_endpoint.iperf_cmd

    @iperf_client.setter
    def iperf_client(self, iperf_cmd):
        """Set moler Command object for iperf client"""
        self.client_endpoint.iperf_cmd = iperf_cmd

    @iperf_client.deleter
    def iperf_client(self):
        """Delete moler Command object of iperf client"""
        del self.client_endpoint.iperf_cmd

    @property
    def iperf_server(self):
        """Access moler Command object for iperf server"""
        return self.server_endpoint.iperf_cmd

    @iperf_server.setter
    def iperf_server(self, iperf_cmd):
        """Set moler Command object for iperf server"""
        self.server_endpoint.iperf_cmd = iperf_cmd

    @iperf_server.deleter
    def iperf_server(self):
        """Delete moler Command object of iperf server"""
        del self.server_endpoint.iperf_cmd

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        self.server_endpoint.prepare_host_device()
        self.client_endpoint.prepare_host_device()
        self.iperf_server = self.server_endpoint.get_server_command_object(self.client_endpoint.endpoint_ip)
        self.iperf_client = self.client_endpoint.get_client_command_object(self.server_endpoint.endpoint_ip, self.port)
        self._build_publisher()

        self.iperf_server.start(timeout=self.duration + 0.5 + 2.0)  # start server in background
        time.sleep(0.1)  # give server chance to start  # TODO: change to started server observer
        self.iperf_client.start(timeout=self.duration + 1.5)  # start client in background
        time.sleep(0.1)  # give client chance to detect failure if it can't start

        if self.iperf_server.done():    # done just after start? Means failed to start.
            self.iperf_client.cancel()
            self.iperf_server.result()  # will re-raise exceptions stored inside command
        else:
            self.server_endpoint.register_timeout_adjuster()
        if self.iperf_client.done():    # done just after start? Means failed to start.
            self.iperf_server.cancel()
            self.iperf_client.result()  # will re-raise exceptions stored inside command
        else:
            self.client_endpoint.register_timeout_adjuster()

    def _build_publisher(self):
        """
        Build IperfPublisher.

        Should be called after creation of self.iperf_client and self.iperf_server
        """
        self._publisher = publisher.IperfPublisher(iperf_direction=self.direction,
                                                   port=self.port,
                                                   ue_ip=self.ue_ip,
                                                   app_server_ip=self.app_server_ip,
                                                   iperf_client=self.iperf_client,
                                                   iperf_server=self.iperf_server,
                                                   logger=self.logger)

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        if not self._was_started():
            raise UeProcedureError("Data Transfer wasn't started yet")

        self.unsubscribe_from_both_directions()
        self._stop_iperf_commands()
        self._statistics = iperf_result.get_statistics(self.direction, self.port, self.client_endpoint, self.server_endpoint)
        self._close_iperf_endpoints_connections()

    def _stop_iperf_commands(self):
        if self.iperf_client.running():
            self.iperf_client.break_cmd()     # send Ctrl-C to client
        if self.iperf_server.running():
            self.iperf_server.break_cmd()     # send Ctrl-C to server
        if self.iperf_client.running():
            self.iperf_client.await_done(timeout=3)  # await client completion
        if self.iperf_server.running():
            self.iperf_server.await_done(timeout=3)  # await server completion

    def _close_iperf_endpoints_connections(self):
        if self.client_endpoint.host_device.has_established_connection():
            self.client_endpoint.host_device.remove()
        if self.server_endpoint.host_device.has_established_connection():
            self.server_endpoint.host_device.remove()

    def await_finish(self):
        """
        Wait until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        if not self._was_started():
            raise UeProcedureError("Data Transfer wasn't started yet")

        if self.iperf_client.running():
            self.iperf_client.await_done()  # await client completion
        if self.iperf_server.running():
            self.iperf_server.await_done()  # await server completion
        self.stop()

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        if self._was_started() and self.iperf_client.running() and self.iperf_server.running():
            return True
        return False

    def _was_started(self):
        if (self.iperf_client is None) and (self.iperf_server is None):
            return False
        return True

    def get_data_transfer_statistics(self, **kwargs):
        """
        Get all statistics of data transfer (intermediate results on timeline & final result)
        :return: data transfer statistics.
        """
        return self._statistics

    def get_average_throughput(self, omit=0, end=0, tput_collection_src='iperf'):
        """
        Abstract method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()' if data transfer is already finished
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: data source based on which the average throughput is counted
        :return: avr throughput in unit: Kbits/sec; If data transfer is simultaneous_ul_dl then return {'dl': dl_avr_tput, 'ul': ul_avr_tput}.
        """
        # Verify Average Throughput     TEST_TRAFFIC    tput_min=ul:19Mbits/sec,dl:75Mbits/sec     tput_max=ul:20Mbits/sec,dl:80Mbits/sec
        # Verify Average Throughput     TEST_TRAFFIC    tput_min=19Mbits/sec     tput_max=20Mbits/sec
        # TODO: retrieve interim throughput
        if self._statistics is None:
            raise DataTransferVerificationFailure("Data Transfer statistics not available")
        avr_tput = {'dl': 0.0, 'ul': 0.0}
        for _direction in self._statistics:
            # 'Bandwidth Raw': '5061 Kbits/sec'
            # 'Bandwidth': 632625
            if 'report' in self._statistics[_direction]:
                report = self._statistics[_direction]['report']
                # moler iperf returns bandwidth in Bytes/sec
                avr_tput_value_in_bytes_per_sec = report['Bandwidth']
                # we need bandwith in Kbits/seconds unit
                avr_tput_value = round(avr_tput_value_in_bytes_per_sec * 0.008, 4)
                avr_tput[_direction] = avr_tput_value
            else:
                # TODO: calculate from interim reports
                raise DataTransferVerificationFailure(f"Can't find iperf {_direction} final report")
        if self.direction == 'simultaneous_ul_dl':
            return avr_tput
        if self.direction in avr_tput:
            return avr_tput[self.direction]
        return 0.0  # no throughput for specified direction

    def subscribe(self, subscriber, direction):
        """
        Subscribe for notifications about iperf statistic (at given direction) as it comes.

        NOTE: only one subscriber per direction at a time, to change subscriber you need to unsubscribe first

        Anytime we find iperf server statistics line like:
        [  3]  2.0- 3.0 sec   612 KBytes  5010 Kbits/sec   0.022 ms    0/  426 (0%)
        such line is parsed and published to subscriber

        Subscriber must be function or method with following signature (name doesn't matter):

            def iperf_observer(data_record=None, report=None):
                '''
                :param data_record: dictionary with intermediate iperf statistics
                :param report: dictionary with final iperf statistics
                '''
                ...

        Either data_record is published or report.
        Report is published on last line of iperf statistics summarizing stats for whole period:
        [904]   0.0-10.0 sec   11.8 MBytes   9.86 Mbits/sec   2.618 ms   9/ 8409  (0.11%)

        :param subscriber: function to be called to notify about data.
        """
        self._publisher.subscribe(subscriber, direction)

    def unsubscribe(self, direction):
        """Unsubscribe function/method subscribed via subscribe()"""
        self._publisher.unsubscribe(direction)

    def unsubscribe_from_both_directions(self):
        """Unsubscribe function/method subscribed via subscribe()"""
        self.unsubscribe('ul')
        self.unsubscribe('dl')

    def statistics_iterator(self, direction, next_statistics_timeout=10):
        """
        Generator function iterating over iperf data transfer statistics

        Iterator returns pairs (direction, statistics_for_that_direction)

        :param direction: which direction to iterate on (ul/dl/simultaneous_ul_dl)
        :param next_statistics_timeout: Max timeout to await for next stats. If exceeded we break iteration.

        :return: generator object (iterator) over incoming (direction, stats) of data_transfer
        """
        yield from self._publisher.statistics_iterator(direction, next_statistics_timeout)
